/**
 * RichTextContent.Blocks: a document’s drawn blocks, each as the member that draws its kind.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/rich-text-content.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { useContext, type JSX } from 'solid-js'

import {
  Each,
  claimSlot,
  mergeParts,
  ownerContext,
  richTextPositionAttrs,
  scope,
  type RichTextDrawnBlock,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/rich-text-content.module.css'
import CodeBlock from './CodeBlock'
import Heading from './Heading'
import RichTextContentInlines from './RichTextContentInlines'
import RichTextContentItem from './RichTextContentItem'
import Text from './Text'
import type { RichTextContentOwner } from './RichTextContent'

export interface RichTextContentBlocksProps {
  blocks: RichTextDrawnBlock[]
}

/** RichTextContent.Blocks: a document’s drawn blocks, each as the member that draws its kind. */
export default function RichTextContentBlocks(given: RichTextContentBlocksProps): JSX.Element {
  const props = claimSlot(given)
  const owner =
    useContext(ownerContext<RichTextContentOwner>('RichTextContent')) ??
    ({} as RichTextContentOwner)
  return scope(() => {
    return (
      <Each of={props.blocks} by={(_block, index) => index} renew>
        {(block) => (
          <>
            {block.kind === 'paragraph' ? (
              <Text size={owner.size}>
                <RichTextContentInlines inlines={block.inlines} />
              </Text>
            ) : block.kind === 'heading' ? (
              <Heading level={block.level}>{block.text}</Heading>
            ) : block.kind === 'ownHeading' && block.level === 4 ? (
              <h4 class={styles.heading} data-level={String(block.level)}>
                <RichTextContentInlines inlines={block.inlines} />
              </h4>
            ) : block.kind === 'ownHeading' && block.level === 3 ? (
              <h3 class={styles.heading} data-level={String(block.level)}>
                <RichTextContentInlines inlines={block.inlines} />
              </h3>
            ) : block.kind === 'ownHeading' ? (
              <h2 class={styles.heading} data-level={String(block.level)}>
                <RichTextContentInlines inlines={block.inlines} />
              </h2>
            ) : block.kind === 'list' && block.ordered ? (
              <ol class={styles.list} start={block.start}>
                <Each of={block.items} by={(_entry, position) => position} renew>
                  {(entry) => <RichTextContentItem blocks={entry} />}
                </Each>
              </ol>
            ) : block.kind === 'list' ? (
              <ul class={styles.list}>
                <Each of={block.items} by={(_entry, position) => position} renew>
                  {(entry) => <RichTextContentItem blocks={entry} />}
                </Each>
              </ul>
            ) : block.kind === 'quote' ? (
              <blockquote class={styles.quote}>
                <RichTextContentBlocks blocks={block.blocks} />
              </blockquote>
            ) : block.kind === 'codeBlock' && block.at === null ? (
              <CodeBlock copyable={block.copyable} label={block.language}>
                {block.text}
              </CodeBlock>
            ) : block.kind === 'codeBlock' ? (
              <div {...mergeParts(richTextPositionAttrs(block.at, true, true))}>
                <CodeBlock copyable={block.copyable} label={block.language}>
                  {block.text}
                </CodeBlock>
              </div>
            ) : block.kind === 'later' && block.at === null ? (
              <Text size={owner.size}>{block.text}</Text>
            ) : block.kind === 'later' ? (
              <Text size={owner.size}>
                <span {...mergeParts(richTextPositionAttrs(block.at, true))}>{block.text}</span>
              </Text>
            ) : null}
          </>
        )}
      </Each>
    )
  })
}
